import React, { useState } from 'react';
import SubAdminTable from './SubAdminTable';
import SubAdminRemoveModal from './SubAdminRemoveModal';
import SubAdminViewModal from './SubAdminViewModal';

import { subAdminsData } from '../../../public/data/data';
import SummaryCards from './SummaryCards';

// If you're using an API, define the base URL here
// const API_URL = 'https://your-api.com';

const SubAdminPage = () => {
  const [viewData, setViewData] = useState(null);
  const [removeId, setRemoveId] = useState(null);
  const [admins, setAdmins] = useState(subAdminsData);

  const active = admins.filter((a) => a.status === 'Active');
  const suspended = admins.filter((a) => a.status === 'Suspended');

  // Handler for adding a new sub‑admin (called from SubAdminTable)
  const handleAdd = async (newAdmin) => {
    // Optionally, make an API call
    // const response = await fetch(`${API_URL}/subadmins`, {
    //   method: 'POST',
    //   headers: { 'Content-Type': 'application/json' },
    //   body: JSON.stringify(newAdmin),
    // });
    // const created = await response.json();

    // For now, just add to local state with a unique ID
    const adminToAdd = {
      ...newAdmin,
      id: Date.now(),          // or use crypto.randomUUID()
      lastActive: new Date().toLocaleDateString(),
    };
    setAdmins((prev) => [...prev, adminToAdd]);
  };

  // Handler for removing a sub‑admin
  const handleRemove = async () => {
    try {
      // await fetch(`${API_URL}/subadmins/${removeId}`, {
      //   method: 'DELETE',
      // });
      setAdmins((prev) => prev.filter((a) => a.id !== removeId));
      setRemoveId(null);
    } catch (error) {
      console.error('Failed to delete:', error);
    }
  };

  return (
    <>
      <div className="flex gap-5 justify-around p-4 flex-wrap">
        <SummaryCards
          title="Total Sub Admin"
          count={admins.length}
          users={admins}
          borderColor="border-gray-400"
        />
        <SummaryCards
          title="Active Sub Admin"
          count={active.length}
          users={active}
          borderColor="border-green-500"
        />
        <SummaryCards
          title="Suspended Sub Admin"
          count={suspended.length}
          users={suspended}
          borderColor="border-red-500"
        />
      </div>

      <div className="p-4">
        <SubAdminTable
          data={admins}
          onView={(admin) => setViewData(admin)}
          onRemove={(id) => setRemoveId(id)}
          onAdd={handleAdd}          // <-- Added create handler
        />
      </div>

      {viewData && (
        <SubAdminViewModal data={viewData} onClose={() => setViewData(null)} />
      )}

      {removeId && (
        <SubAdminRemoveModal
          onConfirm={handleRemove}
          onCancel={() => setRemoveId(null)}
          user={admins.find((a) => a.id === removeId)}
        />
      )}
    </>
  );
};

export default SubAdminPage;